#!/bin/bash
cd "$(dirname "$0")"
node server.js & SERVER_PID=$!
echo "Starting collection service with least-populated-first strategy..."
while true; do echo "Finding least populated database..."; NEXT_TARGET=$(node -e "import(\"./db_manager.js\").then(module => { const target = module.findIncompleteDatabase(); if (target) { if (target.type === \"queued\") { console.log(JSON.stringify({ type: \"queued\", bounds: target.bounds })); } else { console.log(JSON.stringify({ type: \"incomplete\", database: target.database.path, points: target.database.count })); } } else { console.log(\"null\"); } });"); if [ "$NEXT_TARGET" = "null" ]; then echo "No incomplete databases found. Waiting 5 minutes before checking again..."; sleep 300; continue; fi; TARGET_TYPE=$(echo $NEXT_TARGET | jq -r ".type"); if [ "$TARGET_TYPE" = "queued" ]; then BOUNDS=$(echo $NEXT_TARGET | jq -r ".bounds | [.minLat, .minLon, .maxLat, .maxLon] | join(\",\")"); echo "Processing queued area with bounds: $BOUNDS"; else DB_PATH=$(echo $NEXT_TARGET | jq -r ".database"); POINTS=$(echo $NEXT_TARGET | jq -r ".points"); echo "Processing database: $DB_PATH (current points: $POINTS)"; DB_NAME=$(basename "$DB_PATH" .db); IFS="_" read -r _ LAT LON <<< "$DB_NAME"; BOUNDS="${LAT},${LON},$(echo "${LAT} + 1" | bc),$(echo "${LON} + 1" | bc)"; fi; echo "Collecting data for bounds: $BOUNDS"; node collect_sparse_points.js --bounds=$BOUNDS; EXIT_CODE=$?; echo "Process exited with code $EXIT_CODE at $(date)"; if [ $EXIT_CODE -eq 0 ]; then echo "Successfully completed collection for current target"; sleep 60; else echo "Process failed. Waiting 5 minutes before trying next target..."; sleep 300; fi; done
